<script>
var tb=document.querySelector('#lt tbody');function calc(){var t=0;tb.querySelectorAll('tr').forEach(function(r){var q=+r.querySelector('[name="qty[]"]').value||0,p=+r.querySelector('[name="rate[]"]').value||0,a=q*p;r.querySelector('.a').textContent=a.toFixed(2);t+=a});document.getElementById('tt').textContent=t.toFixed(2)}
function addRow(o){var tr=document.createElement('tr');tr.innerHTML='<td><input name="name[]" required><input type="hidden" name="pid[]"></td><td><input name="sku[]"></td><td><input type="number" name="qty[]" min="1" value="1" required oninput="calc()"></td><td><input type="number" step="0.01" name="rate[]" required oninput="calc()"></td><td class="n a">0.00</td><td><button type="button" class="g sm" onclick="this.closest(\'tr\').remove();calc()">✕</button></td>';tb.appendChild(tr);tr.querySelector('[name="name[]"]').value=o.name||'';tr.querySelector('[name="pid[]"]').value=o.id||'';tr.querySelector('[name="sku[]"]').value=o.sku||'';tr.querySelector('[name="rate[]"]').value=o.cost||'';calc()}
var tm;document.getElementById('ps').oninput=function(){clearTimeout(tm);var q=this.value.trim(),box=document.getElementById('pr');if(q.length<2){box.innerHTML='';return}tm=setTimeout(function(){fetch('/admin/purchase/api/products?q='+encodeURIComponent(q),{credentials:'same-origin'}).then(function(r){return r.json()}).then(function(a){box.innerHTML='';a.forEach(function(p){var b=document.createElement('button');b.type='button';b.className='g sm';b.style.margin='2px';b.textContent=p.name+(p.sku?' · '+p.sku:'');b.onclick=function(){addRow(p);box.innerHTML='';document.getElementById('ps').value=''};box.appendChild(b)})})},250)};
if(!tb.children.length)addRow({});calc();
</script>@endsection
